style.css:
/* Enchanted Nether — Verity */
:root {
  /* swap these colours if you fancy */
  --my-bg: #100d1c;
  --my-panel: #1b1730;
  --my-purple: #a477ff;
  --my-green: #48e0a0;
  --my-text: #eee9ff;
  --my-muted: #aaa0c5;
}

/* dark backgrounds */
html,
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* headings and text */
h1, h2, h3, h4 {
  color: var(--my-purple) !important;
  font-family: Georgia, serif !important;
}

p, li, label {
  color: var(--my-text) !important;
}

/* links */
a {
  color: var(--my-green) !important;
  transition: color 0.2s ease, text-shadow 0.2s ease !important;
}

a:hover {
  color: var(--my-purple) !important;
  text-shadow: 0 0 10px var(--my-purple) !important;
}

/* panels and cards */
section,
article,
main {
  border-radius: 12px !important;
}

/* buttons */
button,
input[type="button"],
input[type="submit"] {
  background: linear-gradient(135deg, #6942a8, #236d57) !important;
  color: white !important;
  border: 1px solid #a477ff !important;
  border-radius: 9px !important;
  transition: all 0.2s ease !important;
}

button:hover,
input[type="button"]:hover,
input[type="submit"]:hover {
  box-shadow: 0 0 16px #a477ff88 !important;
  transform: translateY(-2px) !important;
}

/* form fields */
input,
textarea,
select {
  background: var(--my-panel) !important;
  color: var(--my-text) !important;
  border: 1px solid #51416f !important;
  border-radius: 8px !important;
}

/* images */
img {
  border-radius: 10px !important;
}

/* selection */
::selection {
  background: var(--my-purple) !important;
  color: white !important;
}
